# model_new.py
import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing FP16 1‑D convolution (stride=1, padding=0, dilation=1, groups=1, no bias)
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv1d_fp16_kernel(const __half* __restrict__ input,
                                   const __half* __restrict__ weight,
                                   __half* __restrict__ output,
                                   int B, int C_in, int C_out,
                                   int L_in, int K, int L_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C_out * L_out;
    if (idx >= total) return;

    int l_out = idx % L_out;
    int tmp   = idx / L_out;
    int c_out = tmp % C_out;
    int b     = tmp / C_out;

    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        int in_base    = b * C_in * L_in + c * L_in + l_out;
        int w_base     = c_out * C_in * K + c * K;
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            __half i = input[in_base + k];
            __half w = weight[w_base + k];
            sum += __half2float(i) * __half2float(w);
        }
    }
    output[idx] = __float2half(sum);
}

torch::Tensor conv1d_fp16(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(),
                "input and weight must be CUDA tensors");
    TORCH_CHECK(input.dtype() == torch::kHalf && weight.dtype() == torch::kHalf,
                "input and weight must be fp16");

    const int B     = input.size(0);
    const int C_in  = input.size(1);
    const int L_in  = input.size(2);
    const int C_out = weight.size(0);
    const int K     = weight.size(2);
    const int L_out = L_in - K + 1;

    auto opts = torch::TensorOptions().dtype(torch::kHalf).device(torch::kCUDA);
    torch::Tensor output = torch::empty({B, C_out, L_out}, opts);

    const int threads = 256;
    const int total   = B * C_out * L_out;
    const int blocks  = (total + threads - 1) / threads;

    conv1d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        B, C_in, C_out, L_in, K, L_out
    );
    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_fp16", &conv1d_fp16, "FP16 1D convolution (CUDA)");
}
'''

# Compile the extension in‑line
conv1d_ext = load_inline(name='conv1d_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['conv1d_fp16'],
                         verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Only the default convolution settings are supported (stride=1, padding=0,
    dilation=1, groups=1, bias=False).
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert stride == 1 and padding == 0 and dilation == 1 and groups == 1 and not bias, \
            "ModelNew only supports the default Conv1d configuration."
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # weight tensor in fp16 on CUDA
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size,
                        dtype=torch.float16, device='cuda')
        )
        # Kaiming uniform initialization (mirrors nn.Conv1d default)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (batch, in_channels, length)  FP16 CUDA tensor
        returns: (batch, out_channels, length_out) FP16 CUDA tensor
        """
        return conv1d_ext.conv1d_fp16(x, self.weight)

# Helper functions used by the test harness
def get_inputs():
    # Example dimensions from the reference test
    batch_size = 32
    in_channels = 64
    length = 131072
    x = torch.rand(batch_size, in_channels, length,
                   dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # Provide the arguments needed to construct ModelNew
    in_channels = 64
    out_channels = 128
    kernel_size = 3
    return [in_channels, out_channels, kernel_size]
